) AS (
  VALUES 
    (626::BIGINT, 'Yuen es super buena gente y siempre tiene disposicion para ayudar, cae muy bien. No califica duro en lo absoluto.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-08-14T00:00:00+00:00'::TIMESTAMPTZ, '5ef37525a01a22496f7ef39d4c3e062449768d314e1aa4e32b8b26d150f9f49f'::TEXT, ARRAY[1150]::BIGINT[]),
    (626::BIGINT, 'Electiva muy entretenida, no califica para nada duro, con que nunca abandone el curso pasa. Es muy importante buscar buen equipo ya que es un solo proyecto largo que requiere de muy buena organización y participación de todos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'a550373a95adc8191d3a3c73fe2fd1ed4419826d99225cd2501d14ee82ac0981'::TEXT, ARRAY[1150]::BIGINT[]),
    (626::BIGINT, 'Muy buena electiva, es divertida y grupal, se entregan como 3 tareas, un proyecto que se desarrolla a partir de semana 6, y como 2 presentaciones de papers, el profe es super relajado con las entregas y se va a clases a trabajar en las asignaciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2026-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'a6c7fce9d8b5acdbce511d674964d322faa15ef5cfde1c671da30115af61ce85'::TEXT, ARRAY[333]::BIGINT[]),
    (626::BIGINT, 'Como electiva es muy buena opción, se aprende bastante y no se hace un curso pesado y el profesor en general es super bueno, así que super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b90dc6a6e845518511d5aa7177c62d27554c648879b2a78810474b9623bc800a'::TEXT, ARRAY[1143]::BIGINT[]),
    (626::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-14T00:00:00+00:00'::TIMESTAMPTZ, '0c99cc45cfa12e7b4e931ced2b3ba5d01e46ca066882a89de1c225c08392a9d2'::TEXT, ARRAY[333]::BIGINT[]),
    (626::BIGINT, 'Las clases teóricas son aburridas, pero de ahí en fuera el curso es excelente. El curso es jugar y experimentar con la RV, lo que hay que programar es sencillo y los trabajos escritos son cortos. Recomendadísimo, y el profe es una tejota, simplemente lo adoro, hasta presta las gafas si lo ocupa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ee3a7d064b06fa4f44dc753dd8f96f511f30b0fa3cc8e1e46c6d752fe5a51927'::TEXT, ARRAY[1143]::BIGINT[]),
    (626::BIGINT, 'El profesor es excelente, da muchísimo apoyo en todos los trabajos. Todos los trabajos son grupales y uno los puede entregar en cualquier momento del semestre. El volumen de trabajo es moderado, por lo que sí hay que tratar de ir al día con todo. Es un 100 asegurado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ba9ca5348ca9b86f71ed419f56603543312f18ccb11638c9c0e1b017a4a967b2'::TEXT, ARRAY[1143]::BIGINT[]),
    (626::BIGINT, 'Es muy linda persona. No hace exámenes ni quices y da una semana para los trabajos en clase y son super faciles. Hace dos proyectos. No aprendimos mucho pero es sumamente tranquilo y comprensivo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a86186f8c2210a5b3a6f34a0e26860d98c0c18abfb56564218a7bab586f95453'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'Excelente profesor, de los más humanos de la carrera, se preocupa demasiado por el estudiante, muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c8ee35393d98141acb4b1ec8db9a6e5916b86597f3fa81283e01f658b1dfd5ff'::TEXT, ARRAY[333]::BIGINT[]),
    (626::BIGINT, 'El profesor es de lo mejor que tiene la escuela, pero en el curso casi no programamos (solo unas tareas cortas en Unity 3D con un setup de VR simulado). Resultó ser casi que exclusivamente teórico (se leen varios papers y se hacen un par de presentaciones).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'de45dbe7a52ca8503e4af9c495fb00214edbfa2891426d6b4cd415b42050596a'::TEXT, ARRAY[1143]::BIGINT[]),
    (626::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '08b15a935183addd3ff203b0a66a7be2ad4d8254c05b2ce2b056b77bef725836'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'El profe es muy bueno, puede que las clases sean un poco aburridas pero se aprende si usted quiere aprender, debe investigar mucho fuera de la clase pero eso si el profe es excelente, le va a brindar toda la ayuda que le solicite, siempre esta dispuesto a dar tutorías extras si es necesario.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'bae0edb6a049ccbe31f9f6e37e4a6a2df70569c63acaca74012f9d5337b56766'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'De los mejores profesores que uno se puede llegar a encontrar durante la carrera, las clases se pueden sentir en ocasiones largas, pero el siempre procura que uno entienda la materia. Los proyectos son claros, si uno llegase a necesitar ayuda el con gusto el ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '000668a4176739be1a5a74d1093e57f7fb7ad4239836d507dc005ac2de5811c2'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Super bueno Yuen. El único problema es que los PDF que deja a veces son un poco confusos y a veces en clase cuesta un poco entenderle. Pero se nota que le preocupa que uno sí aprenda. Deja temas y proyectos muy chivas. Tambien es amable.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'c6aad5a7db2f52a751a141360e47fe80c25a8c1034803a194ddf5a2589536a60'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Este semestre estuvo incapacitado, los pdf sin su explicación se hicieron muy complicados de entender, muy confusos, pero si se tiene la dirección de él todo fluye. Es super amable, se preocupa por uno, muy comprensivo y deja tareas cada 2 semanas y 2 proyectos medio complejos pero no imposibles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '34605b20af2ba467f4f158abcd096347379299e5e621d3f7d17c48d0343f75b9'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Evaluaciones sencillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-08-12T00:00:00+00:00'::TIMESTAMPTZ, '2c3e7904dca6ce7bedd815fcb91f5620577b13388b6ac5c544c6ca588c499fc2'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'Excelente profe, buena nota, se preocupa por el estudiante, se hacen varias tareas que son sencillas y da mucho tiempo para entregarlas y 2 proyectos no dificiles. LLeven POO con él'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'dca20b0d0fd7457329e59f03939fca5dd998ed88ae76f620e4464332b8e30c58'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'Excelente profe. Lleva las cosas al día, los trabajos son claros e interesantes. Hace quices cada cierto tiempo entonces uno va al día con las lecturas. Completamente recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'f2550f1ae1871977eb0d4600d5f73bca20526dd2d42bca1c218d922587e3cfbc'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Un profe que se adaptó de muy buena manera a la virtualidad, un curso muy ameno pero satisfactorio, deja tarea todas las semanas pero hay hasta 3 o 2 semanas de tiempo para entregarlas, 2 proyectos, sencillos pero útiles, responde dudas dentro y fuera de la clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '3d706cbf909ecf3451de34f4a27ede2b0d08d18dd617f3338d23e2b77b91eeb4'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Es de los mejores profesores que he tenido (posiblemente el mejor). Explica claro, las tareas y proyectos son muy fáciles y sirven para entender la materia, se puede pasar sin proyectos. Muy buena persona, se nota que le importa que uno entienda y aprenda y no busca hacerlo a uno sufrir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '7f6df445a825a7ab62a68686ff83a7b1232400e4a9372ed31de516d0f49e3299'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Muy buen profe y muy buena persona, se preocupa porque los estudiantes aprendan, sin llegar a agobiarlos. Proyectos sencillos y trabajos cortos semanales que ayudan a entender mejor la materia. La clase como tal si es un poco aburrida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1aac84f4c05af8a556e5f751e514c6c4c9dd4520844745052c56e47310be51f7'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Es un muy buen profesor, deja dos proyectos, y en realidad son divertidos. Deja una tarea semana aproximadamente pero tampoco es una tarea súper pesada, es lo justo para que aprenda. Súper recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c792c03ec0793201a2425012d0fc30aaf754464cb1160b0a39650e8b313d007c'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, '(Virtual). Exc profe, deja un PDF por semana con la materia y un par de ejercicios, explica un poco y aclara dudas en una clase semanal, 3 proyectos y una tarea semanal si las entrega todas le da pts extra, proyectos 100% logrables y se aprenden mucho con ellos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'c002f8cd0fe27b8d94591ba08080bc88450ecc7bfa5c20cd1cc6cb8abf9fc266'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'El profe es muy buena nota, la revisión es más una retroalimentación para mejorar y eso motiva mucho, siempre está disponible para resolver dudas. En modo virtual da solo una clase a la semana para explicar el pdf y atender dudas, hay que ser bastante autodidacta porque la materia es un poco pobre'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '8fbef7230bfb26dd7d3daa576de44fa2b7faf96468c855fc1f5735bce12106f3'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Las evaluaciones son fáciles, entonces se puede pasar muy fácil. Pero con él prácticamente no se aprende. Deja un PDF a la semana (por lo general de diseño y no de POO). Solo una clase a la semana de 40 min donde solo ve los ejercicios del PDF. Para pasar sí, para aprender NO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0449729d896654646d7e01d7558f1a9c658cf155318241c7399420227bd70b69'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, '(modalidad virtual) Un profesor de primera, constantemente mejorando aspectos como revisiones previas o la opción de entregar tareas semanales al final del curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '78f79f458f5485928e16fc93fb3dc1e5ff4dd2b2e62f7d608d9a0ab334e961ad'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Excelente profesor, si uno tiene dudas lo ayuda, las progras son extensas, pero logrables y bastante interesantes, hace el curso muy llevadero. 100% Recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'acd1605091c39b30d5e0b3c492521d7df7a99ba04e157e51efae2e96cc433589'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'En modalidad virtual las clases fueron cortas ya que se dedicaba a leer y explicar los PDF dejando una tarea pequeña a la semana. Se debe ser MUY autodidacta para avanzar con los proyectos, incluso para aprender JAVA. Sin embargo es muy comprensivo y brinda la ayuda necesaria cuando lo necesite.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'c81275682bb891df105f26706f6701978894b862dee9e3edc13359b609ce1052'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'lo que hace es mandar pdfs con materia, personalmente en clases no aprendi absolutamente nada, pero los proyectos son demasiado chivas, la mayoria son de hacer juegos y se aprende mucho haciendolos, más que aprender en clases, se aprende con los proyectos, si no es autodidacta no se lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-31T00:00:00+00:00'::TIMESTAMPTZ, 'a7564f0b37fdcdab349ac441b817406ee2fb86602d6236b8858ed7458536a4d9'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'Deja un PDF por semana, el cual hay que leer y realizar algunos ejercicios que vienen. Es muy ordenado con las progras, las cuales son simples y deja bastante tiempo para entregarlas; incluso, da más tiempo si el grupo se lo pide. Explica como con pereza.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-28T00:00:00+00:00'::TIMESTAMPTZ, '7126d34dd5592dd08162a56175c768f484730ef9eaae5fe709227ef8241cea04'::TEXT, ARRAY[1030]::BIGINT[]),
    (626::BIGINT, 'Excelente profe, hay que dedicarle tiempo a los trabajos que deja ya que son extensos y se necesita mucha investigación. Los proyectos fueron muy interesantes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-31T00:00:00+00:00'::TIMESTAMPTZ, '0e6b7f723916df25e3be16cb85efe2582779d1fe10d55fdc7639129840f31285'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'El profe se esfuerza bastante para que las clases se entiendan,son de forma asíncronica con pdfs que están bastante bien.Resuelve dudas en sesiones de zoom .No hay exámenes,solo tareas y proyectos.Suele dejar puntos extra en los proyectos.Los proyectos no son muy complicados si los hace con tiempo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '76b9425557c2038401c58aab0f69f3e2d62f98ddc76cd0527e190e24e28aa825'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'A pesar del esfuerzo que puso y su conocimiento dio una mala metodología para estudiantes de primer ingreso, no supo conllevar la enseñanza para los mismos los cuales apenas están entrando a la programación. Se vio reflejado en el número de personas que pasaron el curso. Materia no explicada en clas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '74062e022884a78d0063211a098935dd588860d708a401344772031ed9adba01'::TEXT, ARRAY[1143, 1022]::BIGINT[]),
    (626::BIGINT, 'Muy buen profe, el curso fue unicamente proyectos y tareas. A veces le cuesta darse a entender, pero se nota que sabe de la materia. En la modalidad virtual fue asincronico y era mas facil entender los pdf, muy al grano.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'dac8b26a1a9bcc6783fb725357c60ecb531378dbb50d89379d228f1b285694da'::TEXT, ARRAY[1035]::BIGINT[]),
    (626::BIGINT, 'Profe muy buena nota, desde el inicio del curso dijo que no habrían exámenes ni quices, sólo tareas y progras, las cuales son sencillas y hay buen tiempo, cuesta entenderle en ocaciones pero explica las veces que haga falta, con él es casi de fijo que se pasa, sólo hacer todos los trabajos y se pasa'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '423d4b5fc6a9d9a481eb182b4148a4269eeacfe6cca5633feb4e3c177a3be24c'::TEXT, ARRAY[1035]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
